def vmstat_counters():
    """Reclaim/swap/compaction/fragmentation counters from /proc/vmstat."""
    out = {}
    for line in _read_lines("/proc/vmstat"):
        parts = line.split()
        if len(parts) == 2 and parts[0] in VMSTAT_KEYS:
            out[parts[0]] = parts[1]
    return out


def buddyinfo_summary():
    """Fragmentation overview: free pages per order (0..10) per zone."""
    out = {}
    for line in _read_lines("/proc/buddyinfo"):
        m = re.match(r"Node\s+(\d+),\s+zone\s+(\S+)\s+(.*)", line)
        if not m:
            continue
        counts = m.group(3).split()
        if len(counts) >= 11:
            try:
                out["node%s_%s" % (m.group(1), m.group(2))] = [
                    int(c) for c in counts[:11]]
            except ValueError:
                pass
    return out


def _sudo():
    """sudo that fails fast instead of prompting (non-interactive tool)."""
    return ["sudo", "-n"]


def btrfs_detail():
    """Btrfs allocation/qgroup/rescan/balance detail.

    Best effort: privileged ioctls use `sudo -n` and degrade to None
    without it. Mirrors system-tuning/btrfs/btrfs-status.sh (report mode).
    """
    out = {}
    # --- allocation (Data/Metadata/System + unallocated) ---
    rc, txt = _run(_sudo() + ["btrfs", "filesystem", "usage", "-b", "/"],
                   timeout=20)
    if rc == 0 and txt:
        out["usage_raw_lines"] = len(txt.splitlines())
        usage = {}
        section = None
        for line in txt.splitlines():
            m = re.match(r"^(Data|Metadata|System)(?:,([^:]+))?:\s*$", line)
            if m:
                section = m.group(1).lower()
                usage[section] = {"profile": (m.group(2) or "").strip() or None}
                continue
            if section:
                m2 = re.match(
                    r"^\s*(Device size|Device allocated|Device unallocated|"
                    r"Device missing|Used|Free \(estimated\)):\s*([\d,]+)",
                    line)
                if m2:
                    key = m2.group(1).lower().replace(" ", "_")
                    key = key.replace("(", "").replace(")", "")
                    usage[section][key] = int(m2.group(2).replace(",", ""))
                elif line.strip() and not line[0].isspace():
                    section = None
        if usage:
            out["usage"] = usage
        # "Device unallocated:" (Overall section) has the bytes on one line;
        # the per-device "Unallocated:" section lists them on following lines.
        m = re.search(r"^\s*Device unallocated:\s*([\d,]+)", txt, re.M)
        if m:
            out["unallocated_bytes"] = int(m.group(1).replace(",", ""))
    # --- quota rescan state ---
    rc, txt = _run(_sudo() + ["btrfs", "quota", "rescan", "-s", "/"],
                   timeout=20)
    out["rescan"] = txt.strip().splitlines()[0] if txt.strip() else None
    # --- qgroups, top 5 by exclusive bytes (needs quotas; --raw = bytes) ---
    qgroups = []
    rc, txt = _run(_sudo() + ["btrfs", "qgroup", "show", "-pcre", "--raw", "/"],
                   timeout=30)
    if rc == 0 and txt:
        for line in txt.splitlines()[2:]:
            parts = line.split()
            if len(parts) >= 3:
                try:
                    qgroups.append({"qgroupid": parts[0],
                                    "referenced_bytes": int(parts[1]),
                                    "exclusive_bytes": int(parts[2])})
                except ValueError:
                    pass
        qgroups.sort(key=lambda q: q["exclusive_bytes"], reverse=True)
        out["qgroups_top5_exclusive"] = qgroups[:5]
        out["qgroup_count"] = len(qgroups)
    else:
        out["qgroups_top5_exclusive"] = None
    # --- balance status ---
…
    return out

