def thermals():
    """Thermal sensors: hwmon tree + nvidia-smi (best effort)."""
    out = {}
    try:
        for hw in sorted(os.listdir("/sys/class/hwmon")):
            base = os.path.join("/sys/class/hwmon", hw)
            name = _read(os.path.join(base, "name")) or hw
            temps = {}
            try:
                files = sorted(os.listdir(base))
            except Exception:
                continue
            for f in files:
                m = re.match(r"temp(\d+)_input$", f)
                if not m:
                    continue
                idx = m.group(1)
                label = (_read(os.path.join(base, "temp%s_label" % idx))
                         or "temp" + idx)
                raw = _read(os.path.join(base, f))
                try:
                    temps[label] = round(int(raw) / 1000.0, 1)
                except (TypeError, ValueError):
                    pass
            if temps:
                out[name] = temps
    except Exception:
        pass
    rc, txt = _run(["nvidia-smi", "--query-gpu=temperature.gpu,power.draw",
                    "--format=csv,noheader,nounits"], timeout=15)
    if rc == 0 and txt.strip():
        parts = [p.strip() for p in txt.strip().split(",")]
        out["nvidia_gpu"] = {
            "temperature_c": parts[0] if parts else None,
            "power_draw_w": parts[1] if len(parts) > 1 else None,
        }
    return out


def collect_config():
    sched_name, sched_evidence = detect_scheduler()
    up = _read("/proc/uptime")
    uptime_s = None
    if up:
        try:
            uptime_s = float(up.split()[0])
        except Exception:
            pass
    cfg = {
        "kernel_release": platform.uname().release,
        "kernel_version": platform.uname().version,
        "machine": platform.uname().machine,
        "cmdline": _read("/proc/cmdline"),
        "profile": booted_profile(),
        "scheduler": {"name": sched_name, "evidence": sched_evidence},
        "cpu": cpu_info(),
        "governors": governors(),
        "sched_tunables": sysctl_dir("/proc/sys/kernel", "sched_"),
        "vm_tunables": sysctl_dir("/proc/sys/vm"),
        "meminfo": meminfo(),
        "nvidia_driver": nvidia_driver(),
        "loadavg": list(os.getloadavg()),
        "uptime_s": uptime_s,
        # v2: 2026-09-21 anomaly-hunt collectors
        "anomaly": {
            "sysctl_disk_winners": sysctl_disk_winners(),
            "postboot_writer_probe": postboot_writer_probe(),
            "zswap": zswap_state(),
            "zram": zram_stats(),
            "swap_layout": swap_layout(),
            "mglru": mglru_state(),
            "btrfs": btrfs_state(),
            "smart": smart_state(),
            "failed_services": failed_services(),
            "nvidia_persistenced": nvidia_persistenced_state(),
            # v3: reclaim/swap/compaction counters, fragmentation,
            # btrfs detail, thermals
            "vmstat": vmstat_counters(),
            "buddyinfo": buddyinfo_summary(),
            "btrfs_detail": btrfs_detail(),
            "thermals": thermals(),
        },
    }
    return cfg


# ------------------------------------------------------------ benchmarks ---

def bench_ctx_switch(iters=10000):
    """socketpair ping-pong across fork(): 2 ctx switches per round-trip."""
    a, b = socket.socketpair()
    pid = os.fork()
    if pid == 0:  # child: echo
        a.close()
        try:
            while True:
                data = b.recv(1)
                if not data:
                    break
                b.sendall(b"X")
        except Exception:
            pass
        os._exit(0)
    b.close()
    try:
        # warmup
        for _ in range(200):
            a.sendall(b"X")
            a.recv(1)
        t0 = time.perf_counter()
        for _ in range(iters):
            a.sendall(b"X")
            a.recv(1)
        dt = time.perf_counter() - t0
    finally:
        try:
            a.shutdown(socket.SHUT_RDWR)
        except Exception:
            pass
        a.close()
        os.waitpid(pid, 0)
    return {"us_per_switch": dt / iters / 2 * 1e6, "iters": iters}


